def solve(arr):
    n = len(arr)
    if n == 2:
        return 0  # Only one deletion possible, return first index

    def get_sum_with_deletion(idx):
        # Calculate sum of absolute differences after deleting element at idx
        total = 0
        # Left part: from 0 to idx-1
        for i in range(idx - 1):
            total += abs(arr[i] - arr[i + 1])

        # Right part: from idx to n-2 (after deletion)
        for i in range(idx, n - 1):
            total += abs(arr[i] - arr[i + 1])

        # If idx is at the end, we only have left part
        if idx == n - 1:
            # Only left part (0 to n-2)
            for i in range(n - 2):
                total += abs(arr[i] - arr[i + 1])
        elif idx == 0:
            # Only right part (1 to n-1)
            for i in range(1, n - 1):
                total += abs(arr[i] - arr[i + 1])

        return total

    min_sum = float('inf')
    best_index = 0

    for i in range(n):
        current_sum = get_sum_with_deletion(i)
        if current_sum < min_sum:
            min_sum = current_sum
            best_index = i

    return best_index

